// pillTone maps a status to its color family: ok, warn, bad, off or info.
func pillTone(status string) string {
	switch status {
	case "active", "ok":
		return "ok"
	case "expiring", "warn":
		return "warn"
	case "expired", "bad":
		return "bad"
	case "info":
		return "info"
	}
	return "off"
}

// pillIcon returns the sprite icon of a tone.
func pillIcon(tone string) string {
	switch tone {
	case "ok":
		return "check-circle"
	case "warn":
		return "clock"
	case "bad":
		return "alert"
	case "info":
		return "info"
	}
	return "slash"
}

